import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";

const Quiz = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const passed = localStorage.getItem("level2Passed");
    if (passed !== "true") {
      navigate("/zugriffsfehler");
    }
  }, [navigate]);

  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const correctAnswers = {
    1: "GUTEREISE",
    2: "ZEBRA",
    3: "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
    4: [
      "Es wird für jeden Buchstaben des Klartexts genau ein Schlüsselbuchstabe verwendet.",
      "Es handelt sich um ein polyalphabetisches Verfahren.",
      "Nutzt man das Verfahren mit einem Schlüssel, der nur aus einem Buchstaben 'A' besteht, so unterscheidet sich das Ergebnis nicht von dem einfachen Verschiebeverfahren.",
      "Das Verfahren kann durch eine Häufigkeitsanalyse geknackt werden."
    ],
    5: [
      "Das One-Time-Pad ist absolut sicher und unknackbar.",
      "Das Vorgehen beim Ver- und Entschlüsseln unterscheidet sich nicht vom Vigenère-Verfahren.",
      "Verschiedene Buchstaben im Klartext können mit dem gleichen Buchstaben verschlüsselt werden."
    ]
  };

  const initialSteps = [
    "Häufigkeit gleicher Textabschnitte untersuchen",
    "Abstände zwischen gleichen Abschnitten bestimmen",
    "Teiler der Abstände berechnen",
    "Länge des Schlüsselwortes ermitteln",
    "Häufigkeitsanalyse in Kolonnen durchführen",
    "Schlüssel ermitteln",
    "Geheimtext entschlüsseln"
  ];

  const correctOrder = [...initialSteps];
  const [stepOrder, setStepOrder] = useState(initialSteps);

  const handleChange = (question, value) => {
    setAnswers({ ...answers, [question]: value });
  };

  const handleMultiChange = (question, value) => {
    const current = answers[question] || [];
    if (current.includes(value)) {
      setAnswers({ ...answers, [question]: current.filter(v => v !== value) });
    } else {
      setAnswers({ ...answers, [question]: [...current, value] });
    }
  };

  const handleDragEnd = (result) => {
    if (!result.destination) return;
    const newOrder = Array.from(stepOrder);
    const [moved] = newOrder.splice(result.source.index, 1);
    newOrder.splice(result.destination.index, 0, moved);
    setStepOrder(newOrder);
  };

  const handleSubmit = () => {
    setAnswers({ ...answers, 6: stepOrder });
    setSubmitted(true);
  };

  const isCorrect = (question) => {
    const userAnswer = answers[question];
    const correct = correctAnswers[question];
    if (Array.isArray(correct)) {
      return (
        Array.isArray(userAnswer) &&
        correct.length === userAnswer.length &&
        correct.every((item) => userAnswer.includes(item))
      );
    }
    return (
      userAnswer &&
      userAnswer.toLowerCase().trim() === correct.toLowerCase().trim()
    );
  };

  const isStepOrderCorrect = () =>
    stepOrder.every((step, index) => step === correctOrder[index]);

  return (
    <div>
      <h1 className="text-2xl font-bold mb-6 heading-style">Zwischenprüfung</h1>

      <div className="mb-6">
        <p className="mb-2">
          <b>1.</b> Welcher Klartext ergibt sich, wenn man den Geheimtext <b>'BCZIEIZWZ'</b> mit dem Schlüsselwort <b>'VIGENERE'</b> entschlüsselt?
        </p>
        <input
          type="text"
          className="w-full p-2 rounded bg-white/10"
          onChange={(e) => handleChange(1, e.target.value)}
        />
        {submitted && (
          <p className={isCorrect(1) ? "text-green-500" : "text-red-500"}>
            {isCorrect(1) ? "Richtig!" : "Falsch."}
          </p>
        )}
      </div>

      <div className="mb-6">
        <p className="mb-2">
          <b>2.</b> Welchen Schlüssel hast du mithilfe des Kasiski-Tests zu dem vorgegebenen Geheimtext ermittelt?
        </p>
        <input
          type="text"
          className="w-full p-2 rounded bg-white/10"
          onChange={(e) => handleChange(2, e.target.value)}
        />
        {submitted && (
          <p className={isCorrect(2) ? "text-green-500" : "text-red-500"}>
            {isCorrect(2) ? "Richtig!" : "Falsch."}
          </p>
        )}
      </div>

      <div className="mb-6">
        <p className="mb-2">
          <b>3.</b> Welchen Schlüssel muss man beim Vigenère-Verfahren wählen,
          um eine progressive Verschiebung zu erhalten, die beim ersten
          Buchstaben mit der Verschiebezahl 0 startet und jeden Folgebuchstaben
          um eins mehr verschiebt?
        </p>
        <input
          type="text"
          className="w-full p-2 rounded bg-white/10"
          onChange={(e) => handleChange(3, e.target.value)}
        />
        {submitted && (
          <p className={isCorrect(3) ? "text-green-500" : "text-red-500"}>
            {isCorrect(3) ? "Richtig!" : "Falsch."}
          </p>
        )}
      </div>

      <div className="mb-6">
        <p className="mb-2">
          <b>4.</b> Welche der folgenden Aussagen treffen auf das Vigenère-Verfahren zu?
        </p>
        {[
          "Es wird für jeden Buchstaben des Klartexts genau ein Schlüsselbuchstabe verwendet.",
          "Es handelt sich um ein polyalphabetisches Verfahren.",
          "Nutzt man das Verfahren mit einem Schlüssel, der nur aus einem Buchstaben 'A' besteht, so unterscheidet sich das Ergebnis nicht von dem einfachen Verschiebeverfahren.",
          "Bei längeren Schlüsseln kann das Verfahren mit der Tabula Recta, aber nicht mit einer Chiffrierscheibe entschlüsselt werden.",
          "Das Verfahren kann durch eine Häufigkeitsanalyse geknackt werden."
        ].map((option, i) => (
          <label key={i} className="block">
            <input
              type="checkbox"
              checked={answers[4]?.includes(option) || false}
              onChange={() => handleMultiChange(4, option)}
            />{" "}
            {option}
          </label>
        ))}
        {submitted && (
          <p className={isCorrect(4) ? "text-green-500" : "text-red-500"}>
            {isCorrect(4) ? "Richtig!" : "Falsch."}
          </p>
        )}
      </div>

      <div className="mb-6">
        <p className="mb-2">
          <b>5.</b> Welche der folgenden Aussagen treffen auf das One-Time-Pad zu?
        </p>
        {[
          "Das One-Time-Pad ist absolut sicher und unknackbar.",
          "Die Schlüsselbuchstaben dürfen nur ein einziges Mal verwendet werden.",
          "Das Vorgehen beim Ver- und Entschlüsseln unterscheidet sich nicht vom Vigenère-Verfahren.",
          "Beim One-Time-Pad werden vor allem sehr kurze Schlüsselworte verwendet.",
          "Die Schlüsselübertragung ist beim One-Time-Pad kein Problem, da der Schlüssel innerhalb der verschlüsselten Nachricht mitgeschickt werden kann.",
          "Verschiedene Buchstaben im Klartext können mit dem gleichen Buchstaben verschlüsselt werden."
        ].map((option, i) => (
          <label key={i} className="block">
            <input
              type="checkbox"
              checked={answers[5]?.includes(option) || false}
              onChange={() => handleMultiChange(5, option)}
            />{" "}
            {option}
          </label>
        ))}
        {submitted && (
          <p className={isCorrect(5) ? "text-green-500" : "text-red-500"}>
            {isCorrect(5) ? "Richtig!" : "Falsch."}
          </p>
        )}
      </div>

      <div className="mb-6">
        <p className="mb-2">
          <b>6.</b> Ordne die Schritte beim Vorgehen der Kryptoanalyse (inkl. Kasiski-Test) in der richtigen Reihenfolge an:
        </p>
        <DragDropContext onDragEnd={handleDragEnd}>
          <Droppable droppableId="kasiski">
            {(provided) => (
              <ul
                {...provided.droppableProps}
                ref={provided.innerRef}
                className="bg-white/10 p-2 rounded space-y-2"
              >
                {stepOrder.map((step, index) => (
                  <Draggable key={step} draggableId={step} index={index}>
                    {(provided) => (
                      <li
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                        className="bg-white/20 p-2 rounded cursor-move"
                      >
                        {step}
                      </li>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </ul>
            )}
          </Droppable>
        </DragDropContext>
        {submitted && (
          <p className={isStepOrderCorrect() ? "text-green-500" : "text-red-500"}>
            {isStepOrderCorrect() ? "Richtig!" : "Falsch."}
          </p>
        )}
      </div>

      <button
        onClick={handleSubmit}
        className="mt-4 px-4 py-2 border border-white text-white rounded hover:bg-white hover:text-black transition"
      >
        Prüfung abschließen
      </button>
    </div>
  );
};

export default Quiz;
